def calculate_taxi_fare(distance_km):
    if distance_km < 5:
        rate = 18
    elif distance_km < 15:
        rate = 15
    else:
        rate = 12
    return round(60 + distance_km * rate)

print(calculate_taxi_fare(3))   # 114
print(calculate_taxi_fare(12))  # 240
print(calculate_taxi_fare(20))  # 300
```

