stores = {
    'Store A': (3, 4),
    'Store B': (6, 8),
    'Store C': (5, 12),
    'Store D': (9, 12)
}
hub = (0, 0)

def euclidean_dist(p1, p2):
    x1, y1 = p1
    x2, y2 = p2
    return round(((x2 - x1)**2 + (y2 - y1)**2)**0.5, 2)

for name, coords in stores.items():
    d = euclidean_dist(hub, coords)
    print(f"Hub to {name}: {d:.2f}")
