students = {
    'S101': (78, 85),
    'S102': (45, 52),
    'S103': (92, 94),
    'S104': (62, 68),
    'S105': (38, 41)
}

def grade_letter(avg):
    if avg >= 85:
        return 'A'
    elif avg >= 75:
        return 'B'
    elif avg >= 65:
        return 'C'
    elif avg >= 50:
        return 'D'
    else:
        return 'F'

for sid, scores in students.items():
    m, f = scores
    avg = (m + f) / 2
    grade = grade_letter(avg)
    print(f"{sid}: Average {avg:.1f} -> Grade {grade}")
```

