# 6.1 Function
def calculate_water_bill(usage):
    if usage < 15:
        rate = 18.5
    elif usage < 35:
        rate = 24.0
    else:
        rate = 31.0
    return round(usage * rate + 150)

print(calculate_water_bill(10))  # 335
print(calculate_water_bill(28))  # 822

# 6.2 Monthly Batch
yearly_water = [14, 18, 22, 12, 16, 38, 42, 29, 21, 15, 19, 31]
for month, usage in enumerate(yearly_water, start=1):
    bill = calculate_water_bill(usage)
    print(f"Month {month}: {bill} NOK")
```

